import json
import math
import os
from datetime import timedelta

import joblib
import numpy as np

from django.conf import settings
from django.db.models import Avg, Count, ExpressionWrapper, F, FloatField, StdDev, Sum
from django.db.models.functions import TruncDate
from django.utils import timezone

from sales.models import Sale, SaleItem
from .models import CreditAssessmentLog, MerchantCreditProfile

# Path to trained machine learning model artifact generated by train_model.py
MODEL_PATH = os.path.join(settings.BASE_DIR, 'credit_scoring', 'ml_models', 'credit_scorer.joblib')


def aggregate_pos_features(store):
    """
    Step 1: Queries POS tables (Sale, SaleItem) and extracts raw aggregations
    and statistical metrics over the past 90 days.
    """
    now = timezone.now()
    ninety_days_ago = now - timedelta(days=90)

    # Fetch recent sales for the store
    recent_sales = Sale.objects.filter(store=store, timestamp__gte=ninety_days_ago)
    total_sales_count = recent_sales.count()

    # 1. Total Revenue & Monthly Average
    total_revenue_dec = recent_sales.aggregate(total=Sum('total_amount'))['total'] or 0.00
    total_revenue = float(total_revenue_dec)
    avg_monthly_revenue = total_revenue / 3.0

    # 2. Active Trading Days (out of 90)
    active_days = recent_sales.dates('timestamp', 'day').count()

    # 3. Monthly Transaction Count
    monthly_transaction_count = int(total_sales_count / 3)

    # 4. Gross Margin Calculation
    sales_items = SaleItem.objects.filter(sale__store=store, sale__timestamp__gte=ninety_days_ago)

    cogs = 0.0
    for item in sales_items:
        cost = float(item.cost_price) if hasattr(item, 'cost_price') and item.cost_price else 0.0
        cogs += cost * float(item.quantity)

    gross_profit = total_revenue - cogs
    avg_gross_margin = (gross_profit / total_revenue * 100.0) if total_revenue > 0 else 0.0

    # 5. Volatility Index (Standard Deviation of Daily Revenue / Mean Daily Revenue)
    # Uses Django TruncDate for cross-database compatibility (SQLite & PostgreSQL)
    daily_totals = (
        recent_sales
        .annotate(sale_date=TruncDate('timestamp'))
        .values('sale_date')
        .annotate(daily_rev=Sum('total_amount'))
    )

    daily_rev_list = [float(item['daily_rev']) for item in daily_totals if item['daily_rev'] is not None]

    if len(daily_rev_list) > 1:
        mean_daily = float(np.mean(daily_rev_list))
        std_daily = float(np.std(daily_rev_list))
        volatility_index = float(std_daily / mean_daily) if mean_daily > 0 else 1.0
    else:
        volatility_index = 0.0

    # 6. Inventory Turnover Ratio (Annualized COGS / Stock Valuation)
    inventory_turnover = 0.0
    try:
        from inventory.models import Product
        stock_val = Product.objects.filter(store=store).aggregate(
            val=Sum(ExpressionWrapper(F('quantity') * F('cost_price'), output_field=FloatField()))
        )['val'] or 0.0

        if stock_val > 0:
            inventory_turnover = float((cogs * 4.0) / stock_val)
    except Exception:
        inventory_turnover = 0.0

    return {
        'avg_monthly_revenue': avg_monthly_revenue,
        'avg_gross_margin': avg_gross_margin,
        'active_days_last_90_days': active_days,
        'monthly_transaction_count': monthly_transaction_count,
        'sales_volatility_index': volatility_index,
        'inventory_turnover_ratio': inventory_turnover,
    }


def predict_probability_of_default(feature_dict):
    """
    Step 2: Runs feature vector through the ML model or fallback heuristic engine.
    Returns: Probability of Default (PD) float between 0.0 and 1.0, and model info.
    """
    features = [
        feature_dict.get('business_age_years', 1.0),
        feature_dict.get('number_of_employees', 1),
        feature_dict.get('total_assets', 0.0),
        feature_dict.get('total_liabilities', 0.0),
        1.0 if feature_dict.get('is_zra_registered', False) else 0.0,
        feature_dict.get('avg_monthly_revenue', 0.0),
        feature_dict.get('avg_gross_margin', 0.0),
        feature_dict.get('sales_volatility_index', 0.0),
        feature_dict.get('active_days_last_90_days', 0),
        feature_dict.get('inventory_turnover_ratio', 0.0),
        feature_dict.get('existing_loan_balance', 0.0),
        feature_dict.get('past_defaults_count', 0),
        feature_dict.get('delinquent_days_max', 0),
    ]

    # Try loading serialized Machine Learning model
    if os.path.exists(MODEL_PATH):
        try:
            model = joblib.load(MODEL_PATH)
            # Predict Probability of Default (Class 1 = Default)
            pd = float(model.predict_proba([features])[0][1])
            model_name = "v1.0-ScikitLearn-Pipeline"
            return pd, model_name
        except Exception:
            pass  # Fall back to heuristic engine if inference fails

    # --- FALLBACK HEURISTIC MODEL ---
    risk_points = 0.0

    # Penalty for past defaults
    risk_points += feature_dict.get('past_defaults_count', 0) * 0.35

    # Penalty for low activity (< 45 active trading days out of 90)
    act_days = feature_dict.get('active_days_last_90_days', 0)
    if act_days < 45:
        risk_points += (45 - act_days) * 0.01

    # Penalty for high sales volatility
    vol = feature_dict.get('sales_volatility_index', 0.0)
    if vol > 1.0:
        risk_points += min(vol * 0.1, 0.25)

    # Reward/Penalty based on monthly revenue scale
    rev = feature_dict.get('avg_monthly_revenue', 0.0)
    if rev > 20000:
        risk_points -= 0.15
    elif rev < 5000:
        risk_points += 0.15

    # Reward for formal tax registration (ZRA)
    if feature_dict.get('is_zra_registered', False):
        risk_points -= 0.05

    # Clamp probability of default between 0.02 (2%) and 0.95 (95%)
    pd = min(max(0.50 + risk_points, 0.02), 0.95)
    model_name = "v1.0-RuleEngine-Fallback"

    return pd, model_name


def map_pd_to_credit_score(pd):
    """
    Step 3: Maps Probability of Default (PD) to standard 300 - 850 Credit Score scale.
    Formula: Score = 300 + ( (1 - PD) * 550 )
    """
    score = 300 + int((1.0 - pd) * 550)
    return min(max(score, 300), 850)


def calculate_store_credit_score(store):
    """
    Main Service Function:
    Aggregates POS history, executes risk inference, updates MerchantCreditProfile,
    and logs an audit entry in CreditAssessmentLog.
    """
    # Get or create credit profile
    profile, _ = MerchantCreditProfile.objects.get_or_create(store=store)

    # 1. Gather POS features
    pos_features = aggregate_pos_features(store)

    # 2. Update profile with aggregated POS metrics
    profile.avg_monthly_revenue = pos_features['avg_monthly_revenue']
    profile.avg_gross_margin = pos_features['avg_gross_margin']
    profile.active_days_last_90_days = pos_features['active_days_last_90_days']
    profile.monthly_transaction_count = pos_features['monthly_transaction_count']
    profile.sales_volatility_index = pos_features['sales_volatility_index']
    profile.inventory_turnover_ratio = pos_features['inventory_turnover_ratio']

    # 3. Combine with static profile data for feature vector
    full_feature_dict = {
        'business_age_years': float(profile.business_age_years),
        'number_of_employees': profile.number_of_employees,
        'total_assets': float(profile.total_assets),
        'total_liabilities': float(profile.total_liabilities),
        'is_zra_registered': profile.is_zra_registered,
        'existing_loan_balance': float(profile.existing_loan_balance),
        'past_defaults_count': profile.past_defaults_count,
        'delinquent_days_max': profile.delinquent_days_max,
        **pos_features
    }

    # 4. Predict Risk (Probability of Default)
    pd, model_used = predict_probability_of_default(full_feature_dict)

    # 5. Translate PD to Credit Score (300 to 850)
    credit_score = map_pd_to_credit_score(pd)

    # 6. Maximum Loan Recommendation
    max_loan = float(profile.avg_monthly_revenue) * 2.5 * (credit_score / 850.0)

    # 7. Assign Risk Tier
    if credit_score >= 700:
        tier = 'LOW'
    elif credit_score >= 580:
        tier = 'MEDIUM'
    elif credit_score >= 450:
        tier = 'HIGH'
    else:
        tier = 'VERY_HIGH'

    # 8. Persist updated metrics to profile
    profile.credit_score = credit_score
    profile.probability_of_default = pd
    profile.max_recommended_loan = max_loan
    profile.risk_tier = tier
    profile.ml_model_version = model_used
    profile.feature_importance_json = json.dumps({
        'active_trading_days': profile.active_days_last_90_days,
        'monthly_revenue': float(profile.avg_monthly_revenue),
        'gross_margin_pct': float(profile.avg_gross_margin),
        'volatility_index': float(profile.sales_volatility_index),
        'past_defaults': profile.past_defaults_count
    })
    profile.save()

    # 9. Log assessment event for audit and research evaluation
    CreditAssessmentLog.objects.create(
        profile=profile,
        assigned_score=credit_score,
        probability_of_default=pd,
        risk_tier=tier,
        recommended_loan=max_loan,
        model_algorithm_used=model_used,
        input_snapshot_json=json.dumps(full_feature_dict)
    )

    return profile

